<?php
declare(strict_types=1); session_start();
header('Access-Control-Allow-Origin: http://localhost:3000'); header('Access-Control-Allow-Credentials: true'); header('Access-Control-Allow-Methods: PUT, POST, OPTIONS'); header('Access-Control-Allow-Headers: Content-Type'); header('Content-Type: application/json; charset=utf-8'); if($_SERVER['REQUEST_METHOD']==='OPTIONS'){http_response_code(204);exit;}
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php'; $pdo=getDatabaseConnection(); requireAdmin($pdo); $d=json_decode(file_get_contents('php://input'),true);$id=trim((string)($d['id']??''));$pid=trim((string)($d['product_id']??''));$n=trim((string)($d['variant_name']??''));$v=trim((string)($d['option_value']??''));$a=filter_var($d['price_adjustment']??0,FILTER_VALIDATE_INT);$s=filter_var($d['stock']??0,FILTER_VALIDATE_INT);$img=$d['img_url']??null;if(!$id||!$pid||!$n||!$v||$a===false||$s===false||$s<0){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Invalid variant fields.']);exit;}
$q=$pdo->prepare('SELECT id FROM variants WHERE product_id=:pid AND variant_name=:n AND option_value=:v AND id<>:id');$q->execute(['pid'=>$pid,'n'=>$n,'v'=>$v,'id'=>$id]);if($q->fetch()){http_response_code(409);echo json_encode(['success'=>false,'message'=>'Variant already exists.']);exit;}$q=$pdo->prepare('UPDATE variants SET product_id=:pid,variant_name=:n,option_value=:v,price_adjustment=:a,stock=:s,img_url=:img WHERE id=:id');$q->execute(['pid'=>$pid,'n'=>$n,'v'=>$v,'a'=>$a,'s'=>$s,'img'=>$img,'id'=>$id]);if(!$q->rowCount()){ $c=$pdo->prepare('SELECT id FROM variants WHERE id=:id');$c->execute(['id'=>$id]);if(!$c->fetch()){http_response_code(404);echo json_encode(['success'=>false,'message'=>'Variant not found.']);exit;}}echo json_encode(['success'=>true,'message'=>'Variant updated.']);
